-- 2. Conexiones del LDR corregidas (antes solo tenia 1 terminal)
DELETE FROM kit_conexiones WHERE proyecto_id IN (
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-primero-bach' AND slug = 'estacion-meteorologica-iot') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-segundo-bach' AND slug = 'domotica-inteligente') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-tercero-bach' AND slug = 'monitoreo-automatizacion-iot') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-primero-bach' AND slug = 'luz-automatica') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-primero-bach' AND slug = 'registro-datos-nube') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-tercero-bach' AND slug = 'casa-inteligente-simulada') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-tercero-bach' AND slug = 'monitoreo-remoto-internet') UNION
  (SELECT id FROM kit_proyectos WHERE kit_id = 'kit-lv-primero-bach' AND slug = 'practica-ldr')
) AND componente ILIKE '%LDR%';

